const COURSE_RE=/\[COURSE_TIMES:([^\]]*)\]/;
function courseTimes(notes:string|null){const p=new URLSearchParams((notes||"").match(COURSE_RE)?.[1]||"");return {apps:p.get("apps")||"",entrees:p.get("entrees")||"",dessert:p.get("dessert")||""}}
function setCourseTime(notes:string|null,key:"apps"|"entrees"|"dessert",time:string){const t=courseTimes(notes);t[key]=time;const p=new URLSearchParams();for(const k of ["apps","entrees","dessert"] as const)if(t[k])p.set(k,t[k]);return [(notes||"").replace(COURSE_RE,"").trim(),p.toString()?"[COURSE_TIMES:"+p.toString()+"]":""].filter(Boolean).join("\n")}
