let refreshPending:Promise<boolean>|null=null;
async function refreshCateringSession():Promise<boolean>{
 if(refreshPending)return refreshPending;
 refreshPending=(async()=>{
  try{
   const raw=sessionStorage.getItem("robertos_auth")||localStorage.getItem("robertos_auth");
   const current=raw?JSON.parse(raw):null;
   if(!current?.refresh_token)return false;
   const response=await fetch("https://xtuhannfnvsvvahrzyxj.supabase.co/auth/v1/token?grant_type=refresh_token",{method:"POST",headers:{apikey:KEY,"Content-Type":"application/json"},body:JSON.stringify({refresh_token:current.refresh_token})});
   if(!response.ok)return false;
   const next=await response.json();
   if(!next.access_token||!next.refresh_token)return false;
   const updated={...current,...next};
   sessionStorage.setItem("robertos_auth",JSON.stringify(updated));
   if(localStorage.getItem("robertos_remember_device")==="yes")localStorage.setItem("robertos_auth",JSON.stringify(updated));
   return true;
  }catch{return false}
 })();
 try{return await refreshPending}finally{refreshPending=null}
}
async function cateringFetch(input:string,init:RequestInit={}):Promise<Response>{
 let response=await fetch(input,init);
 if(response.status!==401)return response;
 if(!(await refreshCateringSession()))throw Error("Your session has expired. Please sign in again, then retry saving your event.");
 response=await fetch(input,{...init,headers:{...headers(),...Object.fromEntries(new Headers(init.headers).entries()),Authorization:"Bearer "+token()}});
 return response;
}
