 async function updateDish(dish:EventDish,quantity:number){if(!editing||quantity<0)return;setMenuBusy(true);setError("");try{const r=await fetch("https://xtuhannfnvsvvahrzyxj.supabase.co/rest/v1/catering_menu_items?id=eq."+dish.id,{method:quantity===0?"DELETE":"PATCH",headers:headers(),...(quantity===0?{}:{body:JSON.stringify({quantity})})});if(!r.ok)throw Error("Could not update dish.");await loadDishes(editing)}catch(e){setError(String(e))}finally{setMenuBusy(false)}}
 function startNew(){setBuffetIncluded([...BUFFET_INCLUDED]);setVegetarianLasagna(false);setMenuPackage("");setEventDishes([]);setEditorTab("details");setEditing(null);setForm({...empty,deposit_amount:defaults.in_house_deposit,location:defaults.default_location});setOpen(true);setError("")}
