 async function save(e:React.FormEvent){e.preventDefault();if(!form.event_name.trim()||!form.customer_name.trim()||!form.event_date){setError("Event name, customer and date are required.");return}if(form.start_time&&form.end_time&&form.end_time<=form.start_time){setError("End time must be later than start time on the same day.");return}const overlaps=events.filter(other=>other.id!==editing&&other.status!=="cancelled"&&other.event_date===form.event_date&&other.location.trim().toLowerCase()===form.location.trim().toLowerCase()&&form.start_time&&form.end_time&&other.start_time&&other.end_time&&form.start_time<other.end_time.slice(0,5)&&other.start_time.slice(0,5)<form.end_time);if(overlaps.length&&!window.confirm("Possible scheduling conflict with: "+overlaps.map(x=>x.event_name).join(", ")+". Save this event anyway?"))return;setSaving(true);setError("");try{const body={...form,bartender_employee_ids:(form.bartender_employee_ids||[]).filter(Boolean),customer_email:form.customer_email||null,customer_phone:form.customer_phone||null,start_time:form.start_time||null,end_time:form.end_time||null,guest_count:Number(form.guest_count),deposit_amount:Number(form.deposit_amount),bar_tab_limit:["bar_tab","open_bar"].includes(form.bar_option)?Number(form.bar_tab_limit??0):null};const response=await cateringFetch(API+(editing?"?id=eq."+encodeURIComponent(editing):""),{method:editing?"PATCH":"POST",headers:{...headers(),Prefer:"return=representation"},body:JSON.stringify(body)});if(!response.ok)throw Error("Save failed ("+response.status+"): "+(await response.text()).slice(0,220));const rows=await response.json();if(rows.length!==1)throw Error("Save was not confirmed.");setOpen(false);setEditing(null);await refresh();onChanged?.()}catch(e){setError(String(e))}finally{setSaving(false)}}
