 const unreadCount=events.filter(e=>e.status==="new_inquiry").length;
 const visibleEvents=events.filter(e=>(statusFilter==="all"||e.status===statusFilter)&&(typeFilter==="all"||e.event_type===typeFilter)&&(!dateFrom||e.event_date>=dateFrom)&&(!dateTo||e.event_date<=dateTo)&&[e.event_name,e.customer_name,e.customer_email||"",e.customer_phone||"",e.location,e.event_date].some(value=>value.toLowerCase().includes(search.trim().toLowerCase())));
 function exportBookings(){const columns:[string,(e:EventRecord)=>unknown][]=[["Date",e=>e.event_date],["Event",e=>e.event_name],["Customer",e=>e.customer_name],["Email",e=>e.customer_email],["Phone",e=>e.customer_phone],["Type",e=>e.event_type],["Status",e=>e.status],["Location",e=>e.location],["Start",e=>e.start_time],["End",e=>e.end_time],["Guests",e=>e.guest_count],["Deposit Required",e=>e.deposit_amount],["Deposit Paid (manual)",e=>e.deposit_paid],["Bar Arrangement",e=>e.bar_option],["Bar Tab Limit",e=>e.bar_tab_limit],["Final Charge",e=>(e as EventRecord & {final_charge?:number|null}).final_charge]];const quote=(v:unknown)=>'"'+String(v??"").replaceAll('"','""')+'"';const csv="\\uFEFF"+[columns.map(([name])=>quote(name)).join(","),...visibleEvents.map(e=>columns.map(([,get])=>quote(get(e))).join(","))].join("\\r\\n");const blob=new Blob([csv],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="catering-bookings-"+new Date().toISOString().slice(0,10)+".csv";a.click();URL.revokeObjectURL(url)}
